# Per-site inclusive calendar-date periods to invalidate / remove.
# Keys are site_name values (matched case-insensitively).
# Dates accept YYYY_MM_DD or YYYY-MM-DD.
SITE_PERIOD_OVERRIDE_RULES: dict[str, list[dict[str, str]]] = {
    "RI-Site1": [
        {"start": "2024_07_01", "end": "2025_02_17"},
    ],
    "BC-Site1": [
        {"start": "2024_05_01", "end": "2024_11_25"},
    ],
    "AN-Site1": [
        {"start": "2024_05_01", "end": "2024_09_01"},
        {"start": "2025_05_07", "end": "2025_12_20"},
    ]
