# DCU / unit numbers to invalidate / remove (inclusive range 1107–1117).
UNIT_NUMBER_OVERRIDE_LIST: list[str] = [str(u) for u in range(1107, 1118)]

# Subtract ``decrease_by`` from every breath_number for matching
# (unit_number, patient_id) across all file_write_times.
# patient_id values are stored without the LUCIA- prefix; matching also
# accepts prefixed forms (e.g. LUCIA-RI-0261).
