OVERRIDE_PREFIX = "override_"
INVALID_OVERRIDE_BY_PERIOD = "INVALID_overide_by_period"
INVALID_OVERRIDE_BY_UNIT_NUMBER = "INVALID_overide_by_unit_number"
INVALID_EARLIER_VISIT = "INVALID_earlier_visit"
TEMPR_CHANNEL_ALIASES = frozenset(
    {"tempr", "temp", "temperature", "aux_a", "auxa"}
)


def _normalize_pcb_id(value: Any) -> str:
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return ""
    text = str(value).strip().lower()
    if not text or text in {"nan", "none", "<na>"}:
        return ""
    return text.lstrip("0") or "0"


def _normalize_site_name(value: Any) -> str:
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return ""
    return str(value).strip().lower()


def _normalize_unit_id(value: Any) -> str:
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return ""
    text = str(value).strip()
    if not text or text.lower() in {"nan", "none", "<na>"}:
        return ""
    # Prefer canonical integer form when numeric (1228.0 -> "1228").
    try:
        as_float = float(text)
        if as_float.is_integer():
            return str(int(as_float))
    except (TypeError, ValueError):
        pass
    return text


def _normalize_patient_id_for_override(value: Any) -> str:
    """Strip optional ``LUCIA-`` prefix; compare case-insensitively."""
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return ""
    text = str(value).strip()
    if not text or text.lower() in {"nan", "none", "<na>"}:
        return ""
    upper = text.upper()
    if upper.startswith("LUCIA-"):
        text = text[6:]
    return text.strip().upper()


def _parse_rule_date(value: str) -> pd.Timestamp:
    """Parse YYYY_MM_DD or YYYY-MM-DD into a timezone-naive midnight timestamp."""
    text = str(value).strip().replace("_", "-")
    ts = pd.to_datetime(text, errors="raise")
    if getattr(ts, "tzinfo", None) is not None:
        ts = ts.tz_convert("UTC").tz_localize(None)
    return pd.Timestamp(ts).normalize()


def _lookup_pcb_thresholds(
    pcb_id: Any,
    thresholds_map: dict[str, dict[str, float]],
) -> dict[str, float] | None:
    key = _normalize_pcb_id(pcb_id)
    if not key:
        return None
    for raw_key, thresholds in thresholds_map.items():
        if _normalize_pcb_id(raw_key) == key:
            return thresholds
    return None


def _coerce_signal_to_float_list(value: object) -> list[float]:
    if value is None or (isinstance(value, float) and pd.isna(value)):
        return []
    if isinstance(value, np.ndarray):
        try:
            return np.asarray(value, dtype=float).ravel().tolist()
        except Exception:
            return []
    if isinstance(value, (list, tuple)):
        out: list[float] = []
        for x in value:
            try:
                out.append(float(x))
            except Exception:
                continue
        return out
    return []


def mid11_avg(signal_val: object) -> float:
    """Mean of 11 middle samples (5 left, middle, 5 right)."""
    arr = _coerce_signal_to_float_list(signal_val)
    if not arr:
        return float("nan")
    n = len(arr)
    mid = n // 2
    start = max(0, mid - 5)
    end = min(n, mid + 6)
    window = arr[start:end]
    if not window:
        return float("nan")
    return float(np.nanmean(window))


def temper_status(
    v: float,
    *,
    mu: float,
    sigma: float,
    min_val: float,
    max_val: float,
) -> str:
    """Classify temperature mid11 average as Good / Mid / Bad."""
    if not np.isfinite(v):
        return "Bad"
    if (mu - sigma) < v < (mu + sigma):
        return "VALID_Good"
    if (min_val <= v < (mu - sigma)) or ((mu + sigma) < v <= max_val):
        return "VALID_Mid"
    return "Bad"


def _is_tempr_row(row: pd.Series) -> bool:
    channel = (
        str(row.get("device_channel", ""))
        .strip()
        .lower()
        .replace("-", "_")
        .replace(" ", "_")
    )
    return channel in TEMPR_CHANNEL_ALIASES


def _site_period_mask(
    df: pd.DataFrame,
    site_rules: dict[str, list[dict[str, str]]],
    *,
    site_col: str,
) -> pd.Series:
    """True for rows whose site_name falls in one of the configured date periods."""
    site_norm = df[site_col].map(_normalize_site_name)
    fwt_dates = pd.to_datetime(df["file_write_time"], errors="coerce")
    # Compare on calendar dates; drop tz to avoid tz-aware vs naive issues.
    if getattr(fwt_dates.dt, "tz", None) is not None:
        fwt_dates = fwt_dates.dt.tz_convert("UTC").dt.tz_localize(None)
    fwt_days = fwt_dates.dt.normalize()

    mask = pd.Series(False, index=df.index)
    for site_name, periods in site_rules.items():
        site_key = _normalize_site_name(site_name)
        if not site_key:
            continue
        site_mask = site_norm.eq(site_key)
        if not site_mask.any():
            continue
        period_mask = pd.Series(False, index=df.index)
        for period in periods:
            start = _parse_rule_date(period["start"])
            end = _parse_rule_date(period["end"])
            if end < start:
                raise ValueError(
                    f"Invalid site period for {site_name!r}: end {period['end']!r} "
                    f"is before start {period['start']!r}"
                )
            period_mask |= fwt_days.between(start, end, inclusive="both")
        mask |= site_mask & period_mask
    return mask.fillna(False)


def override_by_site_period(
    df: pd.DataFrame,
    *,
    site_rules: dict[str, list[dict[str, str]]] | None = None,
    site_col: str | None = None,
    remove_matching: bool = False,
    tracker: Tracker | None = None,
) -> pd.DataFrame:
    """
    Temporary override: invalidate files by site + date period.

    For each configured ``site_name`` period (inclusive start/end dates), every
    row whose ``file_write_time`` falls in that window gets::

        aggregated_reason = INVALID_overide_by_period

    By default (``remove_matching=False``) matching rows are only marked invalid
    and kept. Pass ``remove_matching=True`` to drop them. Removals are recorded
    on ``tracker`` when provided.
    """
    if df.empty:
        return df.copy()
    if "file_write_time" not in df.columns:
        raise KeyError("override_by_site_period requires column 'file_write_time'")

    resolved_site_col = site_col
    if resolved_site_col is None:
        resolved_site_col = next(
            (c for c in ("site_name", "endpoint_name") if c in df.columns),
            None,
        )
    if resolved_site_col is None:
        raise KeyError(
            "override_by_site_period requires 'site_name' (or 'endpoint_name')"
        )
    if "aggregated_reason" not in df.columns:
        raise KeyError("override_by_site_period requires column 'aggregated_reason'")

    if tracker is not None:
        tracker.start_stage("override_site_period")

    rules = site_rules if site_rules is not None else SITE_PERIOD_OVERRIDE_RULES
    out = df.copy()
    mask = _site_period_mask(out, rules, site_col=resolved_site_col)
    n_marked = int(mask.sum())
    n_files = int(out.loc[mask, "file_write_time"].nunique()) if n_marked else 0

    if n_marked:
        out.loc[mask, "aggregated_reason"] = INVALID_OVERRIDE_BY_PERIOD

    if tracker is not None:
        tracker.record_config(
            "override_by_site_period",
            {
                "site_col": resolved_site_col,
                "remove_matching": remove_matching,
                "n_rows_marked": n_marked,
                "n_file_write_times": n_files,
                "site_rules": rules,
            },
        )

    if n_marked and remove_matching:
        before = out
        after = out.loc[~mask].copy()
        if tracker is not None:
            tracker.record_filter(
                "override_site_period",
                "site_period",
                before,
                after,
                metadata={
                    "n_file_write_times": n_files,
                    "reason": INVALID_OVERRIDE_BY_PERIOD,
                },
                trace_reason_col="aggregated_reason",
            )
        out = after
    elif tracker is not None:
        tracker.record_filter(
            "override_site_period",
            "site_period",
            df,
            out,
            metadata={
                "n_rows_marked": n_marked,
                "n_file_write_times": n_files,
                "remove_matching": False,
            },
            trace_reason_col="aggregated_reason",
        )

    return out.reset_index(drop=True)


def override_by_unit_number(
    df: pd.DataFrame,
    *,
    unit_numbers: list[str] | tuple[str, ...] | set[str] | None = None,
    unit_col: str | None = None,
    remove_matching: bool = False,
    tracker: Tracker | None = None,
) -> pd.DataFrame:
    """
    Temporary override: invalidate rows by DCU / unit number.

    Every row whose unit id is in ``unit_numbers`` (default
    ``UNIT_NUMBER_OVERRIDE_LIST``, 1107–1117) gets::

        aggregated_reason = INVALID_overide_by_unit_number

    By default (``remove_matching=False``) matching rows are only marked invalid
    and kept. Pass ``remove_matching=True`` to drop them.
    """
    if df.empty:
        return df.copy()

    resolved_unit_col = unit_col
    if resolved_unit_col is None:
        resolved_unit_col = next(
            (c for c in ("unit_id", "unit_number", "Unit_Number") if c in df.columns),
            None,
        )
    if resolved_unit_col is None:
        raise KeyError(
            "override_by_unit_number requires 'unit_id' (or 'unit_number')"
        )
    if "aggregated_reason" not in df.columns:
        raise KeyError("override_by_unit_number requires column 'aggregated_reason'")

    if tracker is not None:
        tracker.start_stage("override_unit_number")

    blocked = {
        str(u).strip()
        for u in (unit_numbers if unit_numbers is not None else UNIT_NUMBER_OVERRIDE_LIST)
        if str(u).strip()
    }
    out = df.copy()
    unit_vals = out[resolved_unit_col].astype(str).str.strip()
    mask = unit_vals.isin(blocked)
    n_marked = int(mask.sum())
    n_units = int(unit_vals.loc[mask].nunique()) if n_marked else 0

    if n_marked:
        out.loc[mask, "aggregated_reason"] = INVALID_OVERRIDE_BY_UNIT_NUMBER

    if tracker is not None:
        tracker.record_config(
            "override_by_unit_number",
            {
                "unit_col": resolved_unit_col,
                "remove_matching": remove_matching,
                "n_rows_marked": n_marked,
                "n_units": n_units,
                "unit_numbers": sorted(blocked, key=lambda x: int(x) if x.isdigit() else x),
            },
        )

    if n_marked and remove_matching:
        before = out
        after = out.loc[~mask].copy()
        if tracker is not None:
            tracker.record_filter(
                "override_unit_number",
                "unit_number",
                before,
                after,
                metadata={
                    "n_units": n_units,
                    "reason": INVALID_OVERRIDE_BY_UNIT_NUMBER,
                },
                trace_reason_col="aggregated_reason",
            )
        out = after
    elif tracker is not None:
        tracker.record_filter(
            "override_unit_number",
            "unit_number",
            df,
            out,
            metadata={
                "n_rows_marked": n_marked,
                "n_units": n_units,
                "remove_matching": False,
            },
            trace_reason_col="aggregated_reason",
        )

    return out.reset_index(drop=True)


def override_temper_reason(
    df: pd.DataFrame,
    *,
    signal_col: str = "modified_signal_cut",
    pcb_thresholds: dict[str, dict[str, float]] | None = None,
    tracker: Tracker | None = None,
) -> pd.DataFrame:
    """
    Temporary override: set ``temper_reason`` from Tempr mid11 averages.

    For each Tempr row whose ``pcb_id`` is in the per-PCB threshold map, compute
    mid11 mean of ``modified_signal_cut`` and classify::

        temper_reason = override_VALID_Good | override_VALID_Mid | override_Bad

    That reason is then written to **all** ``device_channel`` rows that share the
    same ``file_write_time`` (each file has a single Tempr channel), and
    ``aggregated_reason`` is recomputed for those rows.

    ``file_write_time`` values whose PCB is not listed are left unchanged.
    """
    if df.empty:
        return df.copy()
    if signal_col not in df.columns:
        raise KeyError(f"override_temper_reason requires column {signal_col!r}")
    if "temper_reason" not in df.columns:
        raise KeyError("override_temper_reason requires column 'temper_reason'")
    if "file_write_time" not in df.columns:
        raise KeyError("override_temper_reason requires column 'file_write_time'")

    if tracker is not None:
        tracker.start_stage("override_temper_reason")

    thresholds_map = pcb_thresholds if pcb_thresholds is not None else PCB_TEMPER_OVERRIDE_THRESHOLDS
    out = df.copy()
    status_counts: dict[str, int] = {"VALID_Good": 0, "VALID_Mid": 0, "Bad": 0}

    # One Tempr channel per file_write_time → derive reason from that row only.
    fwt_to_reason: dict[Any, str] = {}
    for _, row in out.iterrows():
        if not _is_tempr_row(row):
            continue
        thresholds = _lookup_pcb_thresholds(row.get("pcb_id"), thresholds_map)
        if thresholds is None:
            continue

        fwt = row.get("file_write_time")
        if fwt is None or (isinstance(fwt, float) and pd.isna(fwt)):
            continue

        avg = mid11_avg(row.get(signal_col))
        status = temper_status(
            avg,
            mu=float(thresholds["mu"]),
            sigma=float(thresholds["sigma"]),
            min_val=float(thresholds["min_val"]),
            max_val=float(thresholds["max_val"]),
        )
        fwt_to_reason[fwt] = f"{OVERRIDE_PREFIX}{status}"
        status_counts[status] = status_counts.get(status, 0) + 1

    if not fwt_to_reason:
        n_overridden = 0
    else:
        mask = out["file_write_time"].isin(list(fwt_to_reason.keys()))
        out.loc[mask, "temper_reason"] = out.loc[mask, "file_write_time"].map(fwt_to_reason)
        for idx in out.index[mask]:
            out.at[idx, "aggregated_reason"] = compute_aggregated_reason(out.loc[idx])
        n_overridden = int(mask.sum())

    if tracker is not None:
        tracker.record_config(
            "override_temper_reason",
            {
                "signal_col": signal_col,
                "n_file_write_times": len(fwt_to_reason),
                "n_rows_overridden": n_overridden,
                "status_counts": status_counts,
                "pcb_ids": sorted({_normalize_pcb_id(k) for k in thresholds_map.keys()}),
            },
        )
        tracker.record_filter(
            "override_temper_reason",
            "temper_reason",
            df,
            out,
            metadata={
                "n_file_write_times": len(fwt_to_reason),
                "n_rows_overridden": n_overridden,
                **status_counts,
            },
            trace_reason_col="aggregated_reason",
        )

    return out.reset_index(drop=True)


def _file_key(df: pd.DataFrame) -> pd.Series:
    """(file_write_time as UTC-naive, unit_id) key; tz-aware and naive inputs collide."""
    fwt = pd.to_datetime(df["file_write_time"], errors="coerce", utc=True)
    fwt = fwt.dt.tz_localize(None)
    unit = df["unit_id"].map(_normalize_unit_id)
    return pd.Series(list(zip(fwt, unit)), index=df.index)


def remove_by_updated_overrides(
    features: pd.DataFrame,
    processed: pd.DataFrame,
    *,
    metadata: pd.DataFrame | None = None,
    signal_col: str = "modified_signal_cut",
    pcb_thresholds: dict[str, dict[str, float]] | None = None,
    site_rules: dict[str, list[dict[str, str]]] | None = None,
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """
    Re-apply ``override_temper_reason`` and ``override_by_site_period`` to an
    already-extracted feature table, without re-running preprocessing.

    Rows (one per file, keyed by ``file_write_time`` + ``unit_id``) are removed when:

    - the file's PCB is in ``pcb_thresholds`` and the Tempr mid11 average of
      ``signal_col`` (read from ``processed``) now classifies as ``Bad``;
    - the file's site + date falls in one of ``site_rules`` periods.

    ``pcb_id`` / ``site_name`` are taken from ``metadata`` (e.g. a
    ``df_fine_type_*.xlsx`` table) when given, falling back to ``features``.

    Returns ``(kept, removed)``; ``removed`` holds the identifying columns plus
    ``removal_reason``, ``tempr_mid11_avg``, ``old_temper_reason`` and
    ``new_temper_reason``.
    """
    required = ["file_write_time", "unit_id"]
    for name, frame, cols in (
        ("features", features, required),
        ("processed", processed, [*required, "device_channel"]),
    ):
        missing = [c for c in cols if c not in frame.columns]
        if missing:
            raise KeyError(f"remove_by_updated_overrides: {name} is missing {missing}")
    if signal_col not in processed.columns:
        raise KeyError(f"remove_by_updated_overrides: processed is missing {signal_col!r}")

    thresholds_map = pcb_thresholds if pcb_thresholds is not None else PCB_TEMPER_OVERRIDE_THRESHOLDS
    rules = site_rules if site_rules is not None else SITE_PERIOD_OVERRIDE_RULES

    feat_key = _file_key(features)
    if feat_key.duplicated().any():
        raise ValueError(
            "remove_by_updated_overrides: features has duplicate "
            "(file_write_time, unit_id) keys"
        )

    pcb = features["pcb_id"] if "pcb_id" in features.columns else pd.Series(pd.NA, index=features.index)
    site = features["site_name"] if "site_name" in features.columns else pd.Series(pd.NA, index=features.index)
    if metadata is not None:
        meta_key = _file_key(metadata)
        meta = metadata.assign(_key=meta_key).drop_duplicates("_key").set_index("_key")
        if "pcb_id" in meta.columns:
            pcb = feat_key.map(meta["pcb_id"]).fillna(pcb)
        if "site_name" in meta.columns:
            site = feat_key.map(meta["site_name"]).fillna(site)

    channel = (
        processed["device_channel"].astype(str).str.strip().str.lower()
        .str.replace("-", "_").str.replace(" ", "_")
    )
    tempr = processed.loc[channel.isin(TEMPR_CHANNEL_ALIASES)]
    tempr = tempr.assign(_key=_file_key(tempr)).drop_duplicates("_key").set_index("_key")
    tempr_signal = feat_key.map(tempr[signal_col])
    old_temper = (
        feat_key.map(tempr["temper_reason"])
        if "temper_reason" in tempr.columns
        else pd.Series(pd.NA, index=features.index)
    )

    avg = pd.Series(np.nan, index=features.index, dtype=float)
    new_temper = pd.Series(pd.NA, index=features.index, dtype=object)
    for idx in features.index:
        thresholds = _lookup_pcb_thresholds(pcb.at[idx], thresholds_map)
        if thresholds is None:
            continue
        value = mid11_avg(tempr_signal.at[idx])
        avg.at[idx] = value
        status = temper_status(
            value,
            mu=float(thresholds["mu"]),
            sigma=float(thresholds["sigma"]),
            min_val=float(thresholds["min_val"]),
            max_val=float(thresholds["max_val"]),
        )
        new_temper.at[idx] = f"{OVERRIDE_PREFIX}{status}"

    temper_mask = new_temper.eq(f"{OVERRIDE_PREFIX}Bad").fillna(False).astype(bool)
    site_frame = pd.DataFrame(
        {"site_name": site, "file_write_time": features["file_write_time"]},
        index=features.index,
    )
    period_mask = _site_period_mask(site_frame, rules, site_col="site_name").astype(bool)

    reasons = pd.Series("", index=features.index, dtype=object)
    reasons[temper_mask] = f"INVALID_temper_reason_{OVERRIDE_PREFIX}Bad"
    both = temper_mask & period_mask
    reasons[period_mask & ~temper_mask] = INVALID_OVERRIDE_BY_PERIOD
    reasons[both] = reasons[both] + ";" + INVALID_OVERRIDE_BY_PERIOD
    remove_mask = temper_mask | period_mask

    id_cols = [
        c
        for c in (
            "file_write_time", "unit_id", "patient_id", "breath_number",
            "visit_number", "study_group", "site_name", "pcb_id", "fine_cluster",
        )
        if c in features.columns
    ]
    removed = features.loc[remove_mask, id_cols].copy()
    removed["pcb_id"] = pcb[remove_mask]
    removed["site_name"] = site[remove_mask]
    removed["removal_reason"] = reasons[remove_mask]
    removed["tempr_mid11_avg"] = avg[remove_mask]
    removed["old_temper_reason"] = old_temper[remove_mask]
    removed["new_temper_reason"] = new_temper[remove_mask]

    kept = features.loc[~remove_mask].copy()
    print(
        f"remove_by_updated_overrides: {int(remove_mask.sum())} / {len(features)} rows removed "
        f"(temper Bad: {int(temper_mask.sum())}, site period: {int(period_mask.sum())}, "
        f"both: {int(both.sum())}, no Tempr signal for listed PCB: "
        f"{int((new_temper.notna() & tempr_signal.isna()).sum())})"
    )
    return kept.reset_index(drop=True), removed.reset_index(drop=True)


def keep_last_visit(
    df: pd.DataFrame,
    *,
    patient_col: str = "patient_id",
    file_time_col: str = "file_write_time",
    remove_matching: bool = True,
    tracker: Tracker | None = None,
) -> pd.DataFrame:
    """Keep only a patient's most recent breath session.

    When a patient exhaled more than once, the earlier session's rows are
    marked ``INVALID_earlier_visit`` and (by default) dropped, so only the
    latest ``file_write_time`` per patient reaches feature extraction.
    Sessions are identified by ``file_write_time``: every row sharing a
    patient's newest timestamp is kept, all of that patient's older rows go.

    This removes *traces*, never patients — a patient with two sessions keeps
    the second one and still contributes to the cohort. Patient counts, and
    therefore any patient-level fold partition, are unaffected.

    Set ``remove_matching=False`` to mark the earlier rows without dropping
    them (they stay in the frame carrying the invalid reason).
    """
    required = [patient_col, file_time_col]
    missing = [column for column in required if column not in df.columns]
    if missing:
        raise KeyError(f"keep_last_visit requires missing column(s): {missing}")

    if tracker is not None:
        tracker.start_stage("keep_last_visit")

    out = df.copy()
    if out.empty:
        return out.reset_index(drop=True)

    times = pd.to_datetime(out[file_time_col], errors="coerce", utc=True)
    if times.isna().any():
        n_bad = int(times.isna().sum())
        raise ValueError(
            f"keep_last_visit: {n_bad} row(s) have an unparsable "
            f"{file_time_col!r}"
        )

    latest = times.groupby(out[patient_col]).transform("max")
    mask = times < latest
    n_marked = int(mask.sum())
    n_patients = int(out.loc[mask, patient_col].nunique())
    n_sessions = int(
        pd.Series(list(zip(out.loc[mask, patient_col], times[mask]))).nunique()
    ) if n_marked else 0

    if "aggregated_reason" in out.columns:
        out.loc[mask, "aggregated_reason"] = INVALID_EARLIER_VISIT

    print(
        f"keep_last_visit: {n_marked} row(s) from {n_sessions} earlier "
        f"session(s) across {n_patients} patient(s) "
        f"{'removed' if remove_matching else 'marked'}"
    )

    if tracker is not None:
        tracker.record_config(
            "keep_last_visit",
            {
                "patient_col": patient_col,
                "file_time_col": file_time_col,
                "remove_matching": remove_matching,
                "n_rows_marked": n_marked,
                "n_patients_affected": n_patients,
                "n_earlier_sessions": n_sessions,
            },
        )

    if n_marked and remove_matching:
        before = out
        after = out.loc[~mask].copy()
        if tracker is not None:
            tracker.record_filter(
                "keep_last_visit",
                "earlier_visit",
                before,
                after,
                metadata={
                    "n_patients_affected": n_patients,
                    "n_earlier_sessions": n_sessions,
                    "reason": INVALID_EARLIER_VISIT,
                },
                trace_reason_col="aggregated_reason",
            )
        out = after
    elif tracker is not None:
        tracker.record_filter(
            "keep_last_visit",
            "earlier_visit",
            df,
            out,
            metadata={
                "n_rows_marked": n_marked,
                "n_patients_affected": n_patients,
                "remove_matching": False,
            },
            trace_reason_col="aggregated_reason",
        )

    return out.reset_index(drop=True)


def override_breath_number(
    df: pd.DataFrame,
    *,
    rules: list[dict[str, Any]] | None = None,
    patient_col: str = "patient_id",
    unit_col: str = "unit_id",
    breath_col: str = "breath_number",
    file_time_col: str = "file_write_time",
    visit_col: str = "visit_number",
    tracker: Tracker | None = None,
) -> pd.DataFrame:
    """Decrease ``breath_number`` for selected (unit, patient) pairs.

    For every rule in ``BREATH_NUMBER_DECREASE_RULES`` (or ``rules``), all rows
    matching that ``unit_number`` + ``patient_id`` — across every
    ``file_write_time`` — have ``breath_number`` decreased by ``decrease_by``.

    ``patient_id`` matching accepts both bare site IDs (``RI-0261``) and
    LUCIA-prefixed forms (``LUCIA-RI-0261``).

    Raises
    ------
    ValueError
        If any matched row would get ``breath_number < 1`` after the decrease.
    """
    active_rules = rules if rules is not None else BREATH_NUMBER_DECREASE_RULES
    required = [patient_col, unit_col, breath_col, file_time_col]
    missing = [column for column in required if column not in df.columns]
    if missing:
        raise KeyError(
            f"override_breath_number requires missing column(s): {missing}"
        )

    if tracker is not None:
        tracker.start_stage("override_breath_number")

    out = df.copy()
    audit_columns = [
        "patient_id",
        "unit_id",
        "file_write_time",
        "visit_number",
        "orignal_breath_number",
        "overide_breath_number",
        "decrease_by",
    ]
    if out.empty or not active_rules:
        audit = pd.DataFrame(columns=audit_columns)
        if tracker is not None:
            tracker.record_breath_number_override(audit)
            tracker.record_config(
                "override_breath_number",
                {
                    "patient_col": patient_col,
                    "unit_col": unit_col,
                    "breath_col": breath_col,
                    "file_time_col": file_time_col,
                    "visit_col": visit_col,
                    "n_rules": len(active_rules),
                    "n_breath_files": 0,
                    "n_changed_breath_files": 0,
                    "n_rows_overridden": 0,
                },
            )
            tracker.record(
                "override_breath_number",
                "breath_number",
                len(df),
                len(out),
                metadata={
                    "n_breath_files": 0,
                    "n_changed_breath_files": 0,
                    "rows_removed": 0,
                },
                df_after=out,
            )
        return out.reset_index(drop=True)

    decrease_map: dict[tuple[str, str], int] = {}
    for rule in active_rules:
        unit_key = _normalize_unit_id(rule.get("unit_number"))
        patient_key = _normalize_patient_id_for_override(rule.get("patient_id"))
        try:
            decrease_by = int(rule.get("decrease_by"))
        except (TypeError, ValueError) as exc:
            raise ValueError(
                f"Invalid decrease_by in breath decrease rule: {rule!r}"
            ) from exc
        if not unit_key or not patient_key:
            raise ValueError(
                f"Breath decrease rule needs unit_number and patient_id: {rule!r}"
            )
        if decrease_by < 0:
            raise ValueError(
                f"decrease_by must be >= 0, got {decrease_by} in rule {rule!r}"
            )
        key = (unit_key, patient_key)
        if key in decrease_map and decrease_map[key] != decrease_by:
            raise ValueError(
                f"Conflicting decrease_by values for unit={unit_key!r} "
                f"patient={patient_key!r}: {decrease_map[key]} vs {decrease_by}"
            )
        decrease_map[key] = decrease_by

    unit_keys = out[unit_col].map(_normalize_unit_id)
    patient_keys = out[patient_col].map(_normalize_patient_id_for_override)
    pair_keys = list(zip(unit_keys.to_numpy(), patient_keys.to_numpy()))
    decrease_series = pd.Series(
        [decrease_map.get(key) for key in pair_keys],
        index=out.index,
        dtype="Float64",
    )
    match_mask = decrease_series.notna()
    if not match_mask.any():
        audit = pd.DataFrame(columns=audit_columns)
        if tracker is not None:
            tracker.record_breath_number_override(audit)
            tracker.record_config(
                "override_breath_number",
                {
                    "patient_col": patient_col,
                    "unit_col": unit_col,
                    "breath_col": breath_col,
                    "file_time_col": file_time_col,
                    "visit_col": visit_col,
                    "n_rules": len(active_rules),
                    "n_matched_rules": 0,
                    "n_breath_files": 0,
                    "n_changed_breath_files": 0,
                    "n_rows_overridden": 0,
                    "rules": list(active_rules),
                },
            )
            tracker.record(
                "override_breath_number",
                "breath_number",
                len(df),
                len(out),
                metadata={
                    "n_breath_files": 0,
                    "n_changed_breath_files": 0,
                    "rows_removed": 0,
                },
                df_after=out,
            )
        return out.reset_index(drop=True)

    original_breath = pd.to_numeric(out.loc[match_mask, breath_col], errors="coerce")
    decrease_matched = decrease_series.loc[match_mask].astype(float)
    if original_breath.isna().any():
        bad = out.loc[match_mask].loc[original_breath.isna()]
        sample = bad[[unit_col, patient_col, file_time_col, breath_col]].head(10)
        raise ValueError(
            "override_breath_number found non-numeric breath_number on matched "
            f"rows; examples:\n{sample}"
        )

    new_breath = original_breath - decrease_matched
    below_one = new_breath < 1
    if below_one.any():
        bad = out.loc[match_mask].loc[below_one].copy()
        bad["_original_breath_number"] = original_breath.loc[below_one]
        bad["_decrease_by"] = decrease_matched.loc[below_one]
        bad["_new_breath_number"] = new_breath.loc[below_one]
        sample = (
            bad[
                [
                    unit_col,
                    patient_col,
                    file_time_col,
                    "_original_breath_number",
                    "_decrease_by",
                    "_new_breath_number",
                ]
            ]
            .drop_duplicates()
            .head(20)
        )
        raise ValueError(
            "override_breath_number would yield breath_number < 1 for "
            f"{int(below_one.sum())} row(s). Examples:\n{sample.to_string(index=False)}"
        )

    out.loc[match_mask, breath_col] = new_breath.astype("Int64")

    audit_source_cols = [patient_col, unit_col, file_time_col, breath_col]
    has_visit = visit_col in out.columns
    if has_visit:
        audit_source_cols.append(visit_col)

    matched = out.loc[match_mask, audit_source_cols].copy()
    matched["_decrease_by"] = decrease_matched.astype(int).to_numpy()
    matched["_orignal_breath_number"] = original_breath.astype("Int64").to_numpy()
    matched["_overide_breath_number"] = (
        matched[breath_col].astype("Int64").to_numpy()
    )
    # One audit row per file_write_time under a matched unit/patient.
    audit = (
        matched.drop_duplicates(
            subset=[unit_col, patient_col, file_time_col],
            keep="first",
        )
        .rename(
            columns={
                patient_col: "patient_id",
                unit_col: "unit_id",
                file_time_col: "file_write_time",
                **({visit_col: "visit_number"} if has_visit else {}),
                "_orignal_breath_number": "orignal_breath_number",
                "_overide_breath_number": "overide_breath_number",
                "_decrease_by": "decrease_by",
            }
        )
    )
    if "visit_number" not in audit.columns:
        audit["visit_number"] = pd.NA
    audit = audit.reindex(columns=audit_columns).reset_index(drop=True)

    if tracker is not None:
        changed_files = int(
            (
                pd.to_numeric(audit["orignal_breath_number"], errors="coerce")
                != pd.to_numeric(audit["overide_breath_number"], errors="coerce")
            ).sum()
        )
        tracker.record_breath_number_override(audit)
        tracker.record_config(
            "override_breath_number",
            {
                "patient_col": patient_col,
                "unit_col": unit_col,
                "breath_col": breath_col,
                "file_time_col": file_time_col,
                "visit_col": visit_col,
                "n_rules": len(active_rules),
                "n_matched_rules": len(
                    {
                        (
                            _normalize_unit_id(r["unit_id"]),
                            _normalize_patient_id_for_override(r["patient_id"]),
                        )
                        for r in audit.to_dict(orient="records")
                    }
                ),
                "n_breath_files": len(audit),
                "n_changed_breath_files": changed_files,
                "n_rows_overridden": int(match_mask.sum()),
                "rules": list(active_rules),
            },
        )
        tracker.record(
            "override_breath_number",
            "breath_number",
            len(df),
            len(out),
            metadata={
                "n_breath_files": len(audit),
                "n_changed_breath_files": changed_files,
                "n_rows_overridden": int(match_mask.sum()),
                "rows_removed": 0,
            },
            df_after=out,
        )

    return out.reset_index(drop=True)
